insert into public.learning_cards (lesson_id, position, title, blocks) values ('929f5529-8352-5127-bf01-ebbff776118e', 1, 'Olympie', '[{"type":"text","text":"Dans la Grèce antique, des épreuves sportives sont organisées à Olympie en l’honneur de Zeus. La tradition les fait commencer en 776 av. J.-C."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('929f5529-8352-5127-bf01-ebbff776118e', 2, 'Un Français relance les Jeux', '[{"type":"keyfigure","value":"1896","label":"Premiers Jeux modernes, à Athènes"},{"type":"text","text":"Pierre de Coubertin convainc le monde de faire renaître les Jeux. Ils ont lieu, comme il se doit, en Grèce."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('929f5529-8352-5127-bf01-ebbff776118e', 3, 'Tous les quatre ans', '[{"type":"text","text":"Les Jeux d’été reviennent tous les quatre ans. Exception notable : Tokyo 2020, reporté à 2021 à cause de la pandémie."}]'::jsonb);
