insert into public.learning_cards (lesson_id, position, title, blocks) values ('3489354b-cd5e-56d2-8acb-2f55ed508d90', 1, 'Cinq anneaux', '[{"type":"text","text":"Dessinés par Coubertin, cinq anneaux entrelacés, bleu, jaune, noir, vert et rouge, sur fond blanc. Ils symbolisent l’union des cinq parties du monde."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('3489354b-cd5e-56d2-8acb-2f55ed508d90', 2, 'La devise', '[{"type":"fact","text":"Citius, Altius, Fortius : « Plus vite, plus haut, plus fort ». En 2021, le mot « ensemble » est ajouté."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('3489354b-cd5e-56d2-8acb-2f55ed508d90', 3, 'La flamme', '[{"type":"text","text":"La flamme est allumée à Olympie avec les rayons du soleil concentrés par un miroir, puis voyage en relais jusqu’à la ville hôte."}]'::jsonb);
