insert into public.learning_cards (lesson_id, position, title, blocks) values ('abdfd9d9-2b3f-5842-a6fa-4929dc702b96', 1, 'Trois fois Paris', '[{"type":"list","items":["1900 : des femmes participent pour la première fois.","1924 : deuxièmes Jeux à Paris.","2024 : troisièmes Jeux, cent ans plus tard."]}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('abdfd9d9-2b3f-5842-a6fa-4929dc702b96', 2, 'L’hiver aussi', '[{"type":"text","text":"Les tout premiers Jeux d’hiver se déroulent à Chamonix en 1924. Les premiers Jeux paralympiques ont lieu à Rome en 1960."}]'::jsonb);
