insert into public.learning_cards (lesson_id, position, title, blocks) values ('6afba038-dbfd-550b-882e-40991ca00c5d', 3, 'Le 10 parfait', '[{"type":"text","text":"À Montréal en 1976, Nadia Comăneci, 14 ans, obtient le premier 10 de l’histoire en gymnastique. Le tableau d’affichage, prévu pour trois chiffres, affiche 1.00."}]'::jsonb);
